const upsertConnectPlatform = `-- name: UpsertConnectPlatform :one
INSERT INTO connect_platforms (slug, label_en, label_ru, enabled, sort_order, updated_by)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (slug) DO UPDATE
SET label_en = EXCLUDED.label_en,
    label_ru = EXCLUDED.label_ru,
    enabled = EXCLUDED.enabled,
    sort_order = EXCLUDED.sort_order,
    updated_at = now(),
    updated_by = EXCLUDED.updated_by
RETURNING slug, label_en, label_ru, enabled, sort_order, updated_at, updated_by
`

type UpsertConnectPlatformParams struct {
	Slug      string      `json:"slug"`
	LabelEn   string      `json:"label_en"`
	LabelRu   string      `json:"label_ru"`
	Enabled   bool        `json:"enabled"`
	SortOrder int32       `json:"sort_order"`
	UpdatedBy pgtype.UUID `json:"updated_by"`
}

func (q *Queries) UpsertConnectPlatform(ctx context.Context, arg UpsertConnectPlatformParams) (ConnectPlatform, error) {
	row := q.db.QueryRow(ctx, upsertConnectPlatform,
		arg.Slug,
		arg.LabelEn,
		arg.LabelRu,
		arg.Enabled,
		arg.SortOrder,
		arg.UpdatedBy,
	)
	var i ConnectPlatform
	err := row.Scan(
		&i.Slug,
		&i.LabelEn,
		&i.LabelRu,
		&i.Enabled,
		&i.SortOrder,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}
